{
  "propositions": [
    {
      "text": "Reproducibility is a defining feature of science.",
      "exactQuote": "Reproducibility is a defining feature of science",
      "blockId": "c-psych-001#block-5"
    },
    {
      "text": "The extent to which reproducibility characterizes current research is unknown.",
      "exactQuote": "the extent to which it characterizes current research is unknown",
      "blockId": "c-psych-001#block-5"
    },
    {
      "text": "The study conducted replications of 100 experimental and correlational studies published in three psychology journals.",
      "exactQuote": "We conducted replications of 100 experimental and correlational studies published in three psychology journals",
      "blockId": "c-psych-001#block-5"
    },
    {
      "text": "The replications used high-powered designs and original materials when available.",
      "exactQuote": "using high-powered designs and original materials when available",
      "blockId": "c-psych-001#block-5"
    },
    {
      "text": "Replication effects had a mean of 0.197 and standard deviation of 0.257.",
      "exactQuote": "Replication effects (Mr = .197, SD = .257)",
      "blockId": "c-psych-001#block-7"
    },
    {
      "text": "Original effects had a mean of 0.403 and standard deviation of 0.188.",
      "exactQuote": "original effects (Mr = .403, SD = .188)",
      "blockId": "c-psych-001#block-7"
    },
    {
      "text": "Replication effects were half the magnitude of original effects, representing a substantial decline.",
      "exactQuote": "were half the magnitude of original effects (Mr = .403, SD = .188), representing a substantial decline",
      "blockId": "c-psych-001#block-7"
    },
    {
      "text": "Ninety-seven percent of original studies had significant results (p < .05).",
      "exactQuote": "Ninety-seven percent of original studies had significant results (p < .05)",
      "blockId": "c-psych-001#block-8"
    },
    {
      "text": "Thirty-six percent of replications had significant results.",
      "exactQuote": "Thirty-six percent of replications had significant results",
      "blockId": "c-psych-001#block-8"
    },
    {
      "text": "Forty-seven percent of original effect sizes were in the 95% confidence interval of the replication effect size.",
      "exactQuote": "47% of original effect sizes were in the 95% confidence interval of the replication effect size",
      "blockId": "c-psych-001#block-8"
    },
    {
      "text": "Thirty-nine percent of effects were subjectively rated to have replicated the original result.",
      "exactQuote": "39% of effects were subjectively rated to have replicated the original result",
      "blockId": "c-psych-001#block-8"
    },
    {
      "text": "If no bias in original results is assumed, combining original and replication results left 68% with significant effects.",
      "exactQuote": "if no bias in original results is assumed, combining original and replication results left 68% with significant effects",
      "blockId": "c-psych-001#block-8"
    },
    {
      "text": "Correlational tests suggest that replication success was better predicted by the strength of original evidence than by characteristics of the original and replication teams.",
      "exactQuote": "Correlational tests suggest that replication success was better predicted by the strength of original evidence than by characteristics of the original and replication teams",
      "blockId": "c-psych-001#block-10"
    },
    {
      "text": "The Reproducibility Project: Psychology began in November 2011.",
      "exactQuote": "The Reproducibility Project: Psychology began in November 2011",
      "blockId": "c-psych-001#block-12"
    },
    {
      "text": "The Reproducibility Project: Psychology finished primary data collection in December 2014.",
      "exactQuote": "finished primary data collection in December 2014",
      "blockId": "c-psych-001#block-12"
    },
    {
      "text": "The Reproducibility Project: Psychology published a summary of the results in August 2015.",
      "exactQuote": "published a summary of the results in August 2015",
      "blockId": "c-psych-001#block-12"
    },
    {
      "text": "The project was coordinated by the Center for Open Science.",
      "exactQuote": "The project was coordinated by the Center for Open Science",
      "blockId": "c-psych-001#block-12"
    },
    {
      "text": "Over 270 contributors earned authorship on the summary report.",
      "exactQuote": "over 270 contributors earned authorship on the summary report",
      "blockId": "c-psych-001#block-12"
    },
    {
      "text": "Eighty-six others provided volunteer support.",
      "exactQuote": "86 others provided volunteer support",
      "blockId": "c-psych-001#block-12"
    }
  ]
}
